const fs=require('fs');const path=require('path');const ROOT=path.resolve(__dirname,'..');const MARK='CE_DATA_WAVE1C_LUMPSUM_20260809';
const rel='articles/investir-grosse-somme-dun-coup-ou-progressivement.html';const p=path.join(ROOT,rel);let s=fs.readFileSync(p,'utf8');if(!s.includes(MARK)){const anchor='<h2>3. Pourquoi l’entrée progressive peut quand même être rationnelle</h2>';if(!s.includes(anchor))throw new Error('Ancre introuvable');const block=`<!-- ${MARK} -->\n<div class="case-study" id="historique-vanguard"><h2>Ce que donne l’historique : 68 % contre 32 %, mais avec un vrai coût dans les mauvais scénarios</h2><p><strong>Données historiques Vanguard, 1976–2022.</strong> L’étude compare un investissement immédiat à une entrée en trois tranches mensuelles sur le MSCI World, avec une mesure du patrimoine après un an. Sur les périodes observées, l’investissement immédiat termine devant l’entrée progressive dans <strong>68 % des cas</strong>. L’entrée progressive termine elle-même devant une conservation intégrale en cash dans <strong>69 % des cas</strong>.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>100 000 $ au départ · portefeuille 100 % actions</th><th>Investissement immédiat</th><th>Entrée sur 3 mois</th></tr></thead><tbody><tr><td>95e percentile après 1 an</td><td><strong>139 453 $</strong></td><td>131 012 $</td></tr><tr><td>Médiane</td><td><strong>111 940 $</strong></td><td>109 580 $</td></tr><tr><td>25e percentile</td><td><strong>102 070 $</strong></td><td>101 531 $</td></tr><tr><td>5e percentile</td><td>82 947 $</td><td><strong>85 906 $</strong></td></tr></tbody></table></div><p><strong>La lecture importante n’est donc pas « 68 % = toujours investir tout de suite ».</strong> Historiquement, le temps passé sur le marché a favorisé l’investissement immédiat dans la majorité des cas. Mais dans les environnements les plus défavorables, l’étalement a mieux protégé le capital à court terme. Le choix est donc un arbitrage entre rendement attendu et risque de regret/capitulation.</p><p>Vanguard montre aussi que, pour un portefeuille 60 % actions / 40 % obligations, la valeur médiane après un an était de 109 360 $ en investissement immédiat contre 107 453 $ avec l’étalement sur trois mois, soit environ <strong>1,8 % d’écart</strong> dans cet historique.</p><p class="source-note">Source : Vanguard Research, février 2023 — <a href="https://corporate.vanguard.com/content/dam/corp/research/pdf/cost_averaging_invest_now_or_temporarily_hold_your_cash.pdf" rel="noopener noreferrer">Cost averaging: Invest now or temporarily hold your cash?</a>. Calculs historiques MSCI World / Bloomberg U.S. Aggregate, 1976–2022. Performances passées non prédictives des performances futures.</p></div>\n`;s=s.replace(anchor,block+anchor);fs.writeFileSync(p,s,'utf8');}
